<?php $slides = \Moves\Services\CmsShowcase::publicSlides(); if ($slides === []) { return; } ?>
<section class="rz-slides" aria-label="Destaques"><?php foreach ($slides as $s): ?><article class="rz-slide rz-slide-<?= $this->e($s['alignment']) ?>"<?= $s['image_path'] ? ' style="background-image:linear-gradient(rgba(5,47,40,.62),rgba(5,47,40,.62)),url(\'' . $this->e($s['image_path']) . '\')"' : '' ?>><div class="container"><h2><?= $this->e($s['title']) ?></h2><div><?= \Moves\Support\HtmlSanitizer::clean($s['content']) ?></div><?php if ($s['link_url'] !== '' && $s['link_label'] !== ''): ?><a class="btn btn-light" href="<?= $this->e($s['link_url']) ?>"><?= $this->e($s['link_label']) ?></a><?php endif; ?></div></article><?php endforeach; ?></section>
